import bundle from "./generated/paper-results.json" with { type: "json" };

// Results of the submitted RoboExam manuscript (CVPR 2027, main-e22e87b).
// Generated by scripts/export-paper-results.py from the manuscript's LaTeX tables
// and frozen episode data; never edit values here by hand.

export type PaperTag = "G" | "R" | "F" | "P" | "T" | "M";
export type PaperSetting = "ID" | "V" | "S" | "B" | "REC";
export const PAPER_SETTINGS: PaperSetting[] = ["ID", "V", "S", "B", "REC"];

type Cell = { n: number; successes: number; subtask: number | null };

export type PaperT1Model = {
  id: string; label: string;
  tags: Record<PaperTag, { tsr: number; score: number }>;
  overall: { tsr: number; score: number };
  summary: { tsr: number; subtask: number; vqa: number; score: number };
  settings: Record<PaperSetting, { tsr: number; subtask: number }>;
};
export type PaperT2Model = {
  id: string; label: string;
  tags: Record<PaperTag, { ee: number; pred: number }>;
  overall: { ee: number; pred: number };
  metrics: { psnr: number; ssim: number; jepa: number; jedi: number; smoothness: number; mmse: number; subject: number; eePos: number; eeRot: number };
  settings: Record<PaperSetting, { eePos: number; mmse: number }>;
};
export type PaperT3Model = {
  id: string; label: string;
  tags: Record<PaperTag, { tsr: number; score: number }>;
  overall: { tsr: number; score: number };
  summary: { tsr: number; subtask: number };
  settings: Record<PaperSetting, { tsr: number; subtask: number | null }>;
  cases: number;
  tasks: Record<string, Partial<Record<PaperSetting, Cell>>>;
};
export type PaperRealScope = { sr: number; subtask: number; successes: number; n: number };
export type PaperRealTaskId = "Buttons" | "Towel" | "Puzzle";
export type PaperT4Model = {
  id: string; label: string;
  overall: { sr: number; subtask: number; n: number };
  tasks: Record<PaperRealTaskId, {
    label: string; extraLabel: string;
    ordinary: PaperRealScope; extra: PaperRealScope;
    conditions: Record<"ID" | "V" | "S" | "B", { successes: number; n: number }>;
  }>;
};
export type PaperHybrid = { id: "direct" | "forecast"; label: string; tsr: number; subtask: number; settings: Record<PaperSetting, number> };

export type PaperResults = {
  schemaVersion: "roboexam.paper-results.v1";
  paper: { title: string; manuscript: string; sourceCommit: string | null };
  tags: Record<PaperTag, { tasks: number }>;
  tasks: { id: string; origin: "RoboDojo" | "new"; tags: PaperTag[]; conditionalTags: PaperTag[]; requirement: string }[];
  tracks: { T1: PaperT1Model[]; T2: PaperT2Model[]; T3: PaperT3Model[]; T4: PaperT4Model[] };
  hybrid: PaperHybrid[];
  sources: Record<string, string>;
};

export const paperResults = bundle as PaperResults;
export const PAPER_VERSION = paperResults.paper.manuscript;
export const PAPER_REAL_TASKS: PaperRealTaskId[] = ["Buttons", "Towel", "Puzzle"];
/** Every T1–T3 model runs the same 600 simulation cases (24 tasks × 5 conditions × 5). */
export const PAPER_SIM_CASES = 600;
export const paperT1ModelIds = new Set(paperResults.tracks.T1.map((model) => model.id));
